UPDATE ui.dashboardresultset SET
vcdashboardresultsetschema = ' {
        "ILiveMessageID":"integer",
        "UniqueID":"string",
        "Class":"string",
        "Time":"datetime",
        "PayerVPA":"string",
        "Is_domestic":"integer",
        "channel":"string",
        "PayerName":"string",
        "PayeeVPA":"string",
        "PayeeName":"string",
        "Amount":"float",
        "FRMPass":"boolean",
        "Score" :"integer",
        "FailedRule":"string",
        "Payer Account":"string",
        "Payee Account":"string",
        "decisiondetails":"string",
        "Txn Type":"string",
        "Payee MCC":"integer",
        "Skip Processing":"integer"
     }'::text WHERE
idashboardresultsetid = 36 AND itenantid = 10;

UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{
    "Initial":{
        "All":{
            "All":{
                "All":"select ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end  end  as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast(observations-> ''txn''->>''type'' as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" from analytics.trans where vcclassname in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser AND iorgid =:orgid  and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) and itenantid = :tenantid ORDER BY dttrxntime desc LIMIT 1;"
            }
        }
    },
    "Redirect":{
        "All":{
          "All":{
              "All":"select ilivemessageid as \\"ILiveMessageID\\" , vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' when result->>''status''=''Success'' then ''true'' when result->>''status'' IS NULL then CASE WHEN score > 0 THEN ''false'' WHEN score = 0  THEN ''true'' else NULL end  end  as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\", cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as  \\"PayeeName\\", cast(observations-> ''txn''->>''type'' as text) as \\"Txn Type\\", ipayeemccid as \\"Payee MCC\\",cast(observations-> ''txn''->''attribs''->''skip_processing'' as int) as \\"Skip Processing\\" from analytics.trans where vcmsgid =:msgid and itenantid=:tenantid;"
         }
      }
    },
    "Search":{
            "All": {
                "Account": {
                    "Payer": "WITH valid_classes AS (SELECT vcclassname FROM ui.transactionclasses WHERE iclassid IN (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND iorgid = :orgid AND mappingtype = ''TransactionClass'') OR -1 IN (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND iorgid = :orgid AND mappingtype = ''TransactionClass'') AND itenantid = :tenantid), ranked_trans AS (SELECT t.ilivemessageid as \\"ILiveMessageID\\" , t.dttrxntime as \\"Time\\", observations, result, vcmsgid as \\"UniqueID\\", t.vcclassname as \\"Class\\", dobservationamount as \\"Amount\\", score as \\"Score\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", ipayeemccid as \\"Payee MCC\\", NULL as \\"FailedRule\\", ROW_NUMBER() OVER (ORDER BY t.ilivemessageid DESC) as rn_desc, ROW_NUMBER() OVER (ORDER BY t.ilivemessageid ASC) as rn_asc FROM analytics.trans t JOIN valid_classes vc ON t.vcclassname = vc.vcclassname WHERE t.itenantid = :tenantid AND t.dttrxntime BETWEEN (SELECT DATE_TRUNC(''day'', dttrxntime)  - INTERVAL ''10 days'' FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid) AND (SELECT DATE_TRUNC(''day'', dttrxntime) + INTERVAL ''11 days'' FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid) AND (t.vcpayeraccountexternalid = :vpaAddress)) SELECT \\"ILiveMessageID\\", \\"Time\\", CASE WHEN observations -> ''txn'' -> ''attribs'' ->> ''is_domestic'' IN (''0.0'', ''1.0'', ''-1.0'') THEN observations -> ''txn'' -> ''attribs'' ->> ''is_domestic'' ELSE NULL END AS \\"Is_domestic\\", CASE WHEN observations -> ''txn'' -> ''attribs'' ->> ''txn_type'' = ''Offline'' THEN ''offline'' ELSE ''online'' END as \\"channel\\", result -> ''score'' ->> ''decisiondetails'' as \\"decisiondetails\\", \\"UniqueID\\", \\"Class\\", \\"Amount\\", \\"Score\\", CASE WHEN result ->> ''status'' = ''Failed'' THEN ''false'' WHEN result ->> ''status'' = ''Success'' THEN ''true'' WHEN result ->> ''status'' IS NULL THEN CASE WHEN \\"Score\\" > 0 THEN ''false'' WHEN \\"Score\\" = 0 THEN ''true'' ELSE NULL END END as \\"FRMPass\\", \\"Payer Account\\", \\"PayerVPA\\", \\"Payee Account\\", \\"PayeeVPA\\", \\"FailedRule\\", CAST(observations -> ''observations'' -> ''payerVPA'' ->> ''vpaName'' AS text) as \\"PayerName\\", CAST(observations -> ''observations'' -> ''payeeVPA'' ->> ''vpaName'' AS text) as \\"PayeeName\\", CAST(observations -> ''txn'' ->> ''type'' AS text) as \\"Txn Type\\", \\"Payee MCC\\", CAST(observations -> ''txn'' -> ''attribs'' -> ''skip_processing'' AS int) as \\"Skip Processing\\" FROM ranked_trans WHERE rn_desc BETWEEN (SELECT rn_desc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) - 20 AND (SELECT rn_desc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) + 20 OR rn_asc BETWEEN (SELECT rn_asc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) - 20 AND (SELECT rn_asc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) + 20 ORDER BY \\"ILiveMessageID\\";",
                    "Payee": "WITH valid_classes AS (SELECT vcclassname FROM ui.transactionclasses WHERE iclassid IN (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND iorgid = :orgid AND mappingtype = ''TransactionClass'') OR -1 IN (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND iorgid = :orgid AND mappingtype = ''TransactionClass'') AND itenantid = :tenantid), ranked_trans AS (SELECT t.ilivemessageid as \\"ILiveMessageID\\", t.dttrxntime as \\"Time\\", observations, result, vcmsgid as \\"UniqueID\\", t.vcclassname as \\"Class\\", dobservationamount as \\"Amount\\", score as \\"Score\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", ipayeemccid as \\"Payee MCC\\", NULL as \\"FailedRule\\", ROW_NUMBER() OVER (ORDER BY t.ilivemessageid DESC) as rn_desc, ROW_NUMBER() OVER (ORDER BY t.ilivemessageid ASC) as rn_asc FROM analytics.trans t JOIN valid_classes vc ON t.vcclassname = vc.vcclassname WHERE t.itenantid = :tenantid AND t.dttrxntime BETWEEN (SELECT DATE_TRUNC(''day'', dttrxntime)  - INTERVAL ''10 days'' FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid) AND (SELECT DATE_TRUNC(''day'', dttrxntime) + INTERVAL ''11 days'' FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid) AND (t.vcpayeeaccountexternalid = :vpaAddress)) SELECT \\"ILiveMessageID\\", \\"Time\\", CASE WHEN observations -> ''txn'' -> ''attribs'' ->> ''is_domestic'' IN (''0.0'', ''1.0'', ''-1.0'') THEN observations -> ''txn'' -> ''attribs'' ->> ''is_domestic'' ELSE NULL END AS \\"Is_domestic\\", CASE WHEN observations -> ''txn'' -> ''attribs'' ->> ''txn_type'' = ''Offline'' THEN ''offline'' ELSE ''online'' END as \\"channel\\", result -> ''score'' ->> ''decisiondetails'' as \\"decisiondetails\\", \\"UniqueID\\", \\"Class\\", \\"Amount\\", \\"Score\\", CASE WHEN result ->> ''status'' = ''Failed'' THEN ''false'' WHEN result ->> ''status'' = ''Success'' THEN ''true'' WHEN result ->> ''status'' IS NULL THEN CASE WHEN \\"Score\\" > 0 THEN ''false'' WHEN \\"Score\\" = 0 THEN ''true'' ELSE NULL END END as \\"FRMPass\\", \\"Payer Account\\", \\"PayerVPA\\", \\"Payee Account\\", \\"PayeeVPA\\", \\"FailedRule\\", CAST(observations -> ''observations'' -> ''payerVPA'' ->> ''vpaName'' AS text) as \\"PayerName\\", CAST(observations -> ''observations'' -> ''payeeVPA'' ->> ''vpaName'' AS text) as \\"PayeeName\\", CAST(observations -> ''txn'' ->> ''type'' AS text) as \\"Txn Type\\", \\"Payee MCC\\", CAST(observations -> ''txn'' -> ''attribs'' -> ''skip_processing'' AS int) as \\"Skip Processing\\" FROM ranked_trans WHERE rn_desc BETWEEN (SELECT rn_desc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) - 20 AND (SELECT rn_desc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) + 20 OR rn_asc BETWEEN (SELECT rn_asc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) - 20 AND (SELECT rn_asc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) + 20 ORDER BY \\"ILiveMessageID\\";",
                    "Both": "WITH valid_classes AS (SELECT vcclassname FROM ui.transactionclasses WHERE iclassid IN (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND iorgid = :orgid AND mappingtype = ''TransactionClass'') OR -1 IN (SELECT mappingid FROM ui.webusermapping WHERE webuserid = :loggedinuser AND iorgid = :orgid AND mappingtype = ''TransactionClass'') AND itenantid = :tenantid), ranked_trans AS (SELECT t.ilivemessageid as \\"ILiveMessageID\\", t.dttrxntime as \\"Time\\", observations, result, vcmsgid as \\"UniqueID\\", t.vcclassname as \\"Class\\", dobservationamount as \\"Amount\\", score as \\"Score\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", ipayeemccid as \\"Payee MCC\\", NULL as \\"FailedRule\\", ROW_NUMBER() OVER (ORDER BY t.ilivemessageid DESC) as rn_desc, ROW_NUMBER() OVER (ORDER BY t.ilivemessageid ASC) as rn_asc FROM analytics.trans t JOIN valid_classes vc ON t.vcclassname = vc.vcclassname WHERE t.itenantid = :tenantid AND t.dttrxntime BETWEEN (SELECT DATE_TRUNC(''day'', dttrxntime)  - INTERVAL ''10 days'' FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid) AND (SELECT DATE_TRUNC(''day'', dttrxntime) + INTERVAL ''11 days'' FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid) AND (t.vcpayeraccountexternalid = :vpaAddress OR t.vcpayeeaccountexternalid = :vpaAddress)) SELECT \\"ILiveMessageID\\", \\"Time\\", CASE WHEN observations -> ''txn'' -> ''attribs'' ->> ''is_domestic'' IN (''0.0'', ''1.0'', ''-1.0'') THEN observations -> ''txn'' -> ''attribs'' ->> ''is_domestic'' ELSE NULL END AS \\"Is_domestic\\", CASE WHEN observations -> ''txn'' -> ''attribs'' ->> ''txn_type'' = ''Offline'' THEN ''offline'' ELSE ''online'' END as \\"channel\\", result -> ''score'' ->> ''decisiondetails'' as \\"decisiondetails\\", \\"UniqueID\\", \\"Class\\", \\"Amount\\", \\"Score\\", CASE WHEN result ->> ''status'' = ''Failed'' THEN ''false'' WHEN result ->> ''status'' = ''Success'' THEN ''true'' WHEN result ->> ''status'' IS NULL THEN CASE WHEN \\"Score\\" > 0 THEN ''false'' WHEN \\"Score\\" = 0 THEN ''true'' ELSE NULL END END as \\"FRMPass\\", \\"Payer Account\\", \\"PayerVPA\\", \\"Payee Account\\", \\"PayeeVPA\\", \\"FailedRule\\", CAST(observations -> ''observations'' -> ''payerVPA'' ->> ''vpaName'' AS text) as \\"PayerName\\", CAST(observations -> ''observations'' -> ''payeeVPA'' ->> ''vpaName'' AS text) as \\"PayeeName\\", CAST(observations -> ''txn'' ->> ''type'' AS text) as \\"Txn Type\\", \\"Payee MCC\\", CAST(observations -> ''txn'' -> ''attribs'' -> ''skip_processing'' AS int) as \\"Skip Processing\\" FROM ranked_trans WHERE rn_desc BETWEEN (SELECT rn_desc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) - 20 AND (SELECT rn_desc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) + 20 OR rn_asc BETWEEN (SELECT rn_asc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) - 20 AND (SELECT rn_asc FROM ranked_trans WHERE \\"ILiveMessageID\\" = (SELECT ilivemessageid FROM analytics.trans WHERE vcmsgid = :msgid AND itenantid = :tenantid)) + 20 ORDER BY \\"ILiveMessageID\\";"
